const TEXT_DECODER = new TextDecoder();
const TEXT_ASSETS = {
  "/": { type: "text/html; charset=utf-8", body: "" },
  "/index.html": { type: "text/html; charset=utf-8", body: "" },
  "/style.css": { type: "text/css; charset=utf-8", body: "" },
  "/main.js": { type: "application/javascript; charset=utf-8", body: "" }
};
const BINARY_ASSETS = {
  "/assets/hovertank-prison-planet-protocol-splash.png": { type: "image/png", body: "" },
  "/assets/hovertank-quest-splash.png": { type: "image/png", body: "" },
  "/assets/mountain-panorama.png": { type: "image/png", body: "" },
  "/assets/textures/architecture-armor.jpg": { type: "image/jpeg", body: "" },
  "/assets/textures/architecture-vents.jpg": { type: "image/jpeg", body: "" },
  "/assets/textures/mechanical-ribs.jpg": { type: "image/jpeg", body: "" },
  "/assets/textures/tank-surface.jpg": { type: "image/jpeg", body: "" },
  "/assets/models/Fuel-Tower_001.mtl": { type: "text/plain; charset=utf-8", body: "" },
  "/assets/models/Fuel-Tower_001.obj": { type: "text/plain; charset=utf-8", body: "" }
};
const AUDIO_SOURCE = "https://raw.githubusercontent.com/immortalchorus/road-to-solareth/main";

function decodeText(base64) {
  const bytes = Uint8Array.from(atob(base64), char => char.charCodeAt(0));
  return TEXT_DECODER.decode(bytes);
}

function decodeBinary(base64) {
  return Uint8Array.from(atob(base64), char => char.charCodeAt(0));
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    const pathname = url.pathname === "" ? "/" : url.pathname;
    if (pathname === "/favicon.ico") return new Response(null, { status: 204 });
    const asset = TEXT_ASSETS[pathname];
    if (asset) {
      return new Response(decodeText(asset.body), {
        headers: { "content-type": asset.type, "cache-control": "no-store" }
      });
    }
    const binaryAsset = BINARY_ASSETS[pathname];
    if (binaryAsset) {
      return new Response(decodeBinary(binaryAsset.body), {
        headers: { "content-type": binaryAsset.type, "cache-control": "public, max-age=3600" }
      });
    }
    if (pathname.startsWith("/assets/") && pathname.endsWith(".mp3")) {
      return Response.redirect(AUDIO_SOURCE + pathname, 302);
    }
    if (env.ASSETS) return env.ASSETS.fetch(request);
    return new Response("Not found", { status: 404, headers: { "content-type": "text/plain; charset=utf-8" } });
  }
};
